function setupForm({ doc, call, toast, createToast, $dialog }) {
  const API = "lavanya_service.api.workflow_actions";
  const REPEAT_API = "lavanya_service.api.repeat_complaints";
  const GROUP = "lavanya-quick-actions";
  const BUTTON_LABEL = "Lavanya Actions";

  let modalSeq = 0;

  function notify(message, isError) {
    const text = String(message || "");
    if (isError) {
      if (toast && toast.error) return toast.error(text);
    } else if (toast && toast.success) {
      return toast.success(text);
    }
    if (createToast) {
      createToast({ title: text, icon: isError ? "alert-circle" : "check" });
    } else {
      window.alert(text);
    }
  }

  function ticketName() {
    return doc && doc.name ? String(doc.name) : "";
  }

  function todayString() {
    return new Date().toISOString().slice(0, 10);
  }

  function esc(value) {
    return String(value == null ? "" : value).replace(/[&<>"']/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
    });
  }

  function getStitchStyles() {
    return `
      <style>
        .lv-modal-container { font-family: Inter, sans-serif; color: #1c1a24; }
        .lv-modal-header { display: flex; flex-direction: column; gap: 8px; margin-bottom: 24px; text-align: center; }
        .lv-modal-icon { width: 48px; height: 48px; border-radius: 50%; display: flex; align-items: center; justify-content: center; margin: 0 auto; font-size: 24px; color: #5412dd; background: #e7deff; }
        .lv-modal-icon.error { color: #ba1a1a; background: #ffdad6; }
        .lv-modal-title { font-size: 18px; font-weight: 600; line-height: 24px; }
        .lv-modal-subtitle { font-size: 14px; color: #494456; }
        .lv-form-group { margin-bottom: 16px; text-align: left; }
        .lv-form-label { display: block; font-size: 13px; font-weight: 500; color: #1c1a24; margin-bottom: 4px; }
        .lv-form-input { width: 100%; border: 1px solid #cac3d9; border-radius: 4px; padding: 10px 12px; font-size: 14px; background: #fff; transition: border-color 0.2s; box-sizing: border-box; }
        .lv-form-input:focus { outline: none; border-color: #5412dd; border-width: 2px; padding: 9px 11px; }
        .lv-form-hint { font-size: 12px; color: #7a7487; margin-top: 4px; }
        .lv-btn-row { display: flex; gap: 12px; justify-content: stretch; margin-top: 32px; }
        .lv-btn { flex: 1; padding: 10px; border-radius: 4px; font-size: 14px; font-weight: 600; cursor: pointer; text-align: center; border: 1px solid transparent; }
        .lv-btn-primary { background: #5412dd; color: #fff; }
        .lv-btn-primary:hover { background: #4d00d2; }
        .lv-btn-secondary { background: #fff; border-color: #cac3d9; color: #1c1a24; }
        .lv-btn-secondary:hover { background: #f2ebfa; }
        .lv-error-msg { color: #ba1a1a; font-size: 13px; font-weight: 500; min-height: 18px; margin-top: 8px; text-align: center; }
      </style>
    `;
  }

  function fieldHtml(uid, f) {
    const id = uid + "-" + f.name;
    const req = f.required ? ' <span style="color:#ba1a1a;">*</span>' : "";
    let input;
    if (f.type === "select") {
      const opts = (f.options || [])
        .map(o => '<option value="' + esc(o) + '">' + esc(o) + "</option>")
        .join("");
      input = '<select id="' + id + '" class="lv-form-input"><option value=""></option>' + opts + '</select>';
    } else if (f.type === "date") {
      input = '<input id="' + id + '" type="date" class="lv-form-input" value="' + esc(f.default || "") + '">';
    } else if (f.type === "textarea") {
      input = '<textarea id="' + id + '" rows="3" class="lv-form-input" style="resize:vertical;">' + esc(f.default || "") + '</textarea>';
    } else {
      input = '<input id="' + id + '" type="text" class="lv-form-input" value="' + esc(f.default || "") + '">';
    }
    return (
      '<div class="lv-form-group">' +
      '<label class="lv-form-label" for="' + id + '">' + esc(f.label) + req + "</label>" +
      input +
      (f.hint ? '<div class="lv-form-hint">' + esc(f.hint) + "</div>" : "") +
      "</div>"
    );
  }

  function lavanyaModal(opts) {
    const name = ticketName();
    if (!name) {
      notify("Save the ticket before running a quick action.", true);
      return;
    }
    if (!$dialog) {
      notify("This view does not support quick action dialogs.", true);
      return;
    }

    const fields = opts.fields || [];
    const uid = "lvm-" + ++modalSeq;

    // Stitch Modal HTML
    const html = getStitchStyles() +
      '<div id="' + uid + '" class="lv-modal-container">' +
        '<div class="lv-modal-header">' +
          '<div class="lv-modal-icon' + (opts.iconColor === 'error' ? ' error' : '') + '">' + (opts.icon || '&#9881;') + '</div>' +
          '<div class="lv-modal-title">' + esc(opts.title) + '</div>' +
          (opts.intro ? '<div class="lv-modal-subtitle">' + esc(opts.intro) + '</div>' : '') +
        '</div>' +
        fields.map(f => fieldHtml(uid, f)).join("") +
        '<div id="' + uid + '-err" class="lv-error-msg"></div>' +
        '<div class="lv-btn-row">' +
          '<button id="' + uid + '-cancel" class="lv-btn lv-btn-secondary">Cancel</button>' +
          '<button id="' + uid + '-submit" class="lv-btn lv-btn-primary">' + esc(opts.submitLabel || 'Confirm') + '</button>' +
        '</div>' +
      '</div>';

    const d = $dialog({
      title: "", // Hide standard title
      html: html,
      actions: [] // We render our own buttons
    });

    // We hide the standard Frappe modal header/footer to make it truly custom
    if (d.$wrapper) {
      d.$wrapper.find('.modal-header').hide();
      d.$wrapper.find('.modal-footer').hide();
      d.$wrapper.find('.modal-content').css({ padding: '24px', borderRadius: '12px' });
    }

    setTimeout(() => {
      const cancelBtn = document.getElementById(uid + '-cancel');
      const submitBtn = document.getElementById(uid + '-submit');
      if (cancelBtn) cancelBtn.onclick = () => d.hide();
      if (submitBtn) submitBtn.onclick = async () => {
        const args = Object.assign({ ticket_name: name }, opts.staticArgs || {});
        const missing = [];
        for (let i = 0; i < fields.length; i++) {
          const f = fields[i];
          const el = document.getElementById(uid + "-" + f.name);
          const val = el ? String(el.value || "").trim() : "";
          if (f.required && !val) missing.push(f.label);
          args[f.name] = val;
        }
        const errEl = document.getElementById(uid + "-err");
        if (missing.length) {
          if (errEl) errEl.textContent = "Required: " + missing.join(", ");
          return;
        }
        if (errEl) errEl.textContent = "";

        // Disable button to prevent double-click
        submitBtn.disabled = true;
        submitBtn.textContent = "Processing...";

        try {
          let result = await call(opts.api, args);
          if (result && result.message) result = result.message;
          notify((result && result.message) || "Action completed.", false);
          d.hide();
          setTimeout(() => window.location.reload(), 600);
        } catch (error) {
          submitBtn.disabled = false;
          submitBtn.textContent = opts.submitLabel || 'Confirm';
          const msg = (error && error.messages && error.messages.join(", ")) || (error && error.message) || "Action failed.";
          if (errEl) errEl.textContent = msg; else notify(msg, true);
        }
      };
    }, 100);
  }

  function confirmModal(opts) {
