    action("Check Repeat Complaint", async function () {
      const name = ticketName();
      if (!name) {
        notify("Save the ticket before checking repeat complaints.", true);
        return;
      }
      try {
        let result = await call(REPEAT_API + ".find_repeat_candidates", { ticket_name: name });
        if (result && result.message) result = result.message;
        const candidates = (result && result.candidates) || [];
        if (!candidates.length) {
          notify("No likely repeat complaint found.", false);
          return;
        }
        const options = candidates.map(function (c) {
          const product = [c.brand, c.product_item || c.product_type, c.serial_no].filter(Boolean).join(" / ");
          const label = c.ticket + " [" + (c.status || "") + "] " + (c.customer_name || "") + (product ? " — " + product : "") + " — " + (c.match_reasons || []).join(", ");
          return { value: c.ticket, label: label };
        });

        lavanyaModal({
            title: "Repeat Complaint Suggestions",
            intro: "Select a previous ticket to link as a repeat complaint:",
            icon: '&#128257;', // refresh
            submitLabel: "Confirm Repeat",
            api: REPEAT_API + ".confirm_repeat_complaint",
            fields: [
                { name: "previous_ticket_link", label: "Previous Ticket", type: "select", required: true, options: options.map(o => o.value) } // using value as option
            ]
        });
      } catch (error) {
        notify("Repeat complaint check failed.", true);
      }
    }),

